"""Templated replies for classifier-served Copilot v2 turns.

When the message classifier decides a turn does not need the full agent
(greetings, goodbyes, out-of-scope, ...), this module streams the category's
templated reply from ``copilot_templated_responses.yml`` as AG-UI text events —
the same event vocabulary agent replies use, so the frontend needs no changes.

Stream-only by design: persistence belongs to the lifecycle owner
(``PydanticAICopilot.stream_ag_ui_events``). No LLM calls are made and no
event mapper is involved (there are no pydantic-ai events to map).
"""

from __future__ import annotations

from collections.abc import AsyncIterator
from typing import Any, Final

import structlog

from rasa.builder.copilot.copilot_templated_message_provider import (
    copilot_handler_default_responses,
)
from rasa.builder.copilot.models import ResponseCategory
from rasa.builder.copilot.pydantic_ai import ag_ui_events

structlogger = structlog.get_logger()

# Template keys duplicated from rasa.builder.copilot.response_handling.constants
# on purpose: that package is v1-only and dies with the v1 sunset (S15), while
# the YAML file and this module survive it. Keys are served under their
# existing names — the *_fallback_response rename was explicitly dropped.
_ERROR_FALLBACK_RESPONSE_KEY: Final[str] = "error_fallback_response"
_CATEGORY_TO_RESPONSE_KEY: Final[dict[ResponseCategory, str]] = {
    ResponseCategory.GREETING_DETECTION: "greeting_fallback_response",
    ResponseCategory.GOODBYE_DETECTION: "goodbye_fallback_response",
    ResponseCategory.ROLEPLAY_DETECTION: "roleplay_response",
    ResponseCategory.OUT_OF_SCOPE_DETECTION: "out_of_scope_response",
    ResponseCategory.UNCLEAR_INPUT_DETECTION: "unclear_input_response",
    ResponseCategory.KNOWLEDGE_BASE_ACCESS_REQUESTED: (
        "knowledge_base_access_requested_response"
    ),
    ResponseCategory.RASA_INTRODUCTION_DETECTION: "rasa_introduction_response",
    ResponseCategory.COPILOT_INTRODUCTION_DETECTION: "copilot_introduction_response",
}


class TemplatedResponsesUnavailableError(Exception):
    """Raised when the packaged templated-responses file yielded nothing.

    The YAML ships inside the package, so an empty provider result is a broken
    build; masking it with hardcoded text would hide the packaging bug. The
    lifecycle owner surfaces this as RUN_ERROR.
    """


async def stream_templated_reply(
    response_category: ResponseCategory,
    message_id: str,
) -> AsyncIterator[dict[str, Any]]:
    """Yield the AG-UI text events for one classifier-served reply.

    Same contract as the agent loop's event stream: yields AG-UI event dicts,
    here exactly ``TEXT_MESSAGE_START``, one ``TEXT_MESSAGE_CONTENT`` carrying
    the full templated text, and ``TEXT_MESSAGE_END``.

    Args:
        response_category: The non-COPILOT category the classifier decided.
        message_id: The AG-UI message id to stamp on every event.

    Yields:
        AG-UI event dicts.

    Raises:
        TemplatedResponsesUnavailableError: If the templates file yielded
            nothing to serve (packaging bug).
    """
    text = _templated_reply_text(response_category)
    yield ag_ui_events.text_message_start(message_id)
    yield ag_ui_events.text_message_content(message_id, text)
    yield ag_ui_events.text_message_end(message_id)


def _templated_reply_text(response_category: ResponseCategory) -> str:
    """Resolve the reply text for a category, degrading to the error fallback."""
    responses = copilot_handler_default_responses()
    response_key = _CATEGORY_TO_RESPONSE_KEY.get(response_category)
    text = responses.get(response_key) if response_key else None
    if text is not None:
        return text

    structlogger.warning(
        "copilot_v2.templated_reply.missing_template",
        response_category=response_category.value,
        response_key=response_key,
    )
    fallback = responses.get(_ERROR_FALLBACK_RESPONSE_KEY)
    if fallback is None:
        raise TemplatedResponsesUnavailableError(
            "copilot_templated_responses.yml provided no reply for "
            f"'{response_category.value}' and no error fallback; the packaged "
            "templates file is missing or unreadable."
        )
    return fallback
